mapper.select:

SELECT 
  FROM timeline_entry e
 WHERE e.request_id = #{requestId}



 ORDER BY e.occurred_at ASC, e.id ASC
 LIMIT #{q.limit}


SELECT 
  FROM timeline_entry e
  JOIN timeline_entry_subject s ON s.entry_id = e.id
 WHERE s.subject_type = #{subjectType} AND s.subject_id = #{subjectId}



 ORDER BY e.occurred_at ASC, e.id ASC
 LIMIT #{q.limit}
